<script setup>
import{onMounted,ref}from'vue';import api from '../services/api'
const business=ref(null),report=ref(null),monthly=ref([]),loading=ref(true),error=ref('')
onMounted(async()=>{try{const[b,r,m]=await Promise.all([api.get('/businesses'),api.get('/reports/dashboard'),api.get('/reports/monthly')]);business.value=b.data.data[0];report.value=r.data.data;monthly.value=m.data.data}catch(e){error.value=e.response?.data?.message||'ড্যাশবোর্ড লোড করা যায়নি।'}finally{loading.value=false}})
const money=v=>new Intl.NumberFormat('bn-BD',{maximumFractionDigits:0}).format(Number(v||0))
</script>
<template><section><div class="welcome"><div><p class="eyebrow">OVERVIEW</p><h2>শুভ সকাল, {{business?.name||'ব্যবসার মালিক'}}</h2><p>চলতি মাসের লাইভ ব্যবসায়িক অবস্থা।</p></div><RouterLink class="secondary" to="/reports">রিপোর্ট দেখুন →</RouterLink></div><p v-if="error" class="error">{{error}}</p><p v-if="loading" class="empty">লোড হচ্ছে...</p><template v-if="report"><div class="metrics"><article><span class="metric-icon green">৳</span><div><small>মাসের বিক্রয়</small><strong>৳{{money(report.sales)}}</strong><em>লাইভ API ডেটা</em></div></article><article><span class="metric-icon blue">◉</span><div><small>মাসের সংগ্রহ</small><strong>৳{{money(report.collections)}}</strong><em>সব পেমেন্ট</em></div></article><article><span class="metric-icon amber">▦</span><div><small>কম স্টক</small><strong>{{report.low}}টি পণ্য</strong><em class="warning">পুনঃঅর্ডার প্রয়োজন</em></div></article><article><span class="metric-icon red">!</span><div><small>গ্রাহক বকেয়া</small><strong>৳{{money(report.due)}}</strong><em class="warning">বর্তমান মোট বাকি</em></div></article></div><div class="dashboard-grid"><article class="panel"><div class="panel-title"><div><h3>মাসিক বিক্রয়</h3><small>সর্বশেষ ১২ মাস</small></div></div><div class="report-list"><p v-for="row in monthly" :key="row.month">{{row.month}} <strong>৳{{money(row.sales)}}</strong></p><p v-if="!monthly.length" class="empty">এখনও বিক্রয় নেই।</p></div></article><article class="panel"><div class="panel-title"><div><h3>শাখা কর্মক্ষমতা</h3><small>চলতি মাস</small></div><RouterLink to="/branches">সব দেখুন</RouterLink></div><div class="report-list"><p v-for="row in report.branches" :key="row.branch_id">{{row.branch?.name}} <strong>৳{{money(row.total)}}</strong></p><p v-if="!report.branches.length" class="empty">এখনও শাখাভিত্তিক বিক্রয় নেই।</p></div></article></div></template></section></template>
